import random
from random import choice, randint, random as rnd

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    def count(seq, ch):
        return sum(1 for x in seq if x == ch)

    op_c = count(op, 'C')
    op_d = n - op_c
    my_c = count(my, 'C')

    # If opponent has defected much more than cooperated, punish hard.
    if op_d > op_c + 1:
        # Tit-for-tat oriented retaliation with occasional probing.
        if op[-1] == 'D':
            if n > 95:
                return 'D'
            return 'D' if rng.random() < 0.9 else 'C'
        else:
            return 'C' if rng.random() < 0.85 else 'D'

    # Opponent mostly cooperative: cooperate, but defect opportunistically late.
    if op_d <= op_c:
        # Detect if opponent never retaliates: then exploit.
        can_exploit = True
        for i in range(1, n):
            if my[i - 1] == 'D' and op[i] == 'C':
                # Opponent failed to punish previous defection
                if op_d > 0:
                    can_exploit = False
                    break

        if n >= 90:
            # Last rounds: defect to grab DC payoff if opponent likely cooperates.
            if op[-1] == 'C':
                return 'D'
            return 'C'

        # Mild exploitation chance if we've been very cooperative and opponent forgiving.
        if my_c > n * 0.7 and op_c > n * 0.8 and n > 30:
            if rng.random() < 0.15:
                return 'D'

        return 'C'

    # Mixed case: mirror recent opponent behavior with slight forgiveness.
    recent = op[-5:] if n >= 5 else op
    recent_d = count(recent, 'D')
    if recent_d >= 3:
        return 'D'
    if recent_d == 0:
        return 'C'
    return 'D' if rng.random() < 0.4 else 'C'
